/** Original neutral Pech, nine-slot pack, valuables, taming, collective anger and weapon AI. */
public final class Pech extends Monster implements RangedAttackMob {
    private static final EntityDataAccessor<Byte> VARIANT=SynchedEntityData.defineId(Pech.class,EntityDataSerializers.BYTE),TAMED=SynchedEntityData.defineId(Pech.class,EntityDataSerializers.BYTE);
    private static final EntityDataAccessor<Integer> ANGER=SynchedEntityData.defineId(Pech.class,EntityDataSerializers.INT);
    public final net.minecraft.core.NonNullList<ItemStack> loot=net.minecraft.core.NonNullList.withSize(9,ItemStack.EMPTY);
    public float mumble;public boolean trading,updateAINextTick;private int chargecount;private LivingEntity angryAt;
    private Goal arrowAttack,blastAttack,meleeAttack,avoidPlayer;
    public Pech(EntityType<? extends Pech> type,Level level){super(type,level);if(getNavigation() instanceof GroundPathNavigation ground){ground.setCanOpenDoors(true);ground.setCanPassDoors(true);}setDropChance(EquipmentSlot.MAINHAND,.2f);if(!level.isClientSide)setCombatTask();}
    public static AttributeSupplier.Builder attributes(){return Monster.createMonsterAttributes().add(Attributes.MAX_HEALTH,30).add(Attributes.ATTACK_DAMAGE,6).add(Attributes.MOVEMENT_SPEED,.5);}
    @Override protected void defineSynchedData(SynchedEntityData.Builder builder){super.defineSynchedData(builder);builder.define(VARIANT,(byte)0);builder.define(ANGER,0);builder.define(TAMED,(byte)0);}
    public int variant(){return entityData.get(VARIANT);}
    public void variant(int value){entityData.set(VARIANT,(byte)value);}
    public int anger(){return entityData.get(ANGER);}
    public void anger(int value){entityData.set(ANGER,(int)(short)value);}
    public boolean tamed(){return entityData.get(TAMED)==1;}
    public void tamed(boolean value){entityData.set(TAMED,(byte)(value?1:0));updateAINextTick=true;}
    @Override public Component getName(){return hasCustomName()?getCustomName():Component.translatable("entity.thaumcraft.pech"+(variant()==0?"":"."+variant()));}
    @Override public int getArmorValue(){return Math.min(20,super.getArmorValue()+2);}
    @Override protected void registerGoals(){goalSelector.addGoal(0,new FloatGoal(this));goalSelector.addGoal(1,new Goal(){ {setFlags(EnumSet.of(Flag.MOVE,Flag.JUMP));}public boolean canUse(){return isAlive()&&!isInWater()&&tamed()&&onGround()&&!hurtMarked&&trading;}public void start(){getNavigation().stop();}public void stop(){trading=false;}});goalSelector.addGoal(3,new Pickup());goalSelector.addGoal(5,new OpenDoorGoal(this,true));goalSelector.addGoal(6,new MoveTowardsRestrictionGoal(this,.5));goalSelector.addGoal(6,new MoveThroughVillageGoal(this,1,false,4,()->false));goalSelector.addGoal(9,new RandomStrollGoal(this,.6));goalSelector.addGoal(9,new LookAtPlayerGoal(this,Player.class,3,1));goalSelector.addGoal(10,new LookAtPlayerGoal(this,Mob.class,8));goalSelector.addGoal(11,new RandomLookAroundGoal(this));targetSelector.addGoal(1,new HurtByTargetGoal(this));arrowAttack=new RangedAttackGoal(this,.6,20,50,15);blastAttack=new RangedAttackGoal(this,.6,20,30,15);meleeAttack=new Cultist.Melee(this,.6);avoidPlayer=new AvoidEntityGoal<>(this,Player.class,8,.5,.6);}
    public void setCombatTask(){if(meleeAttack==null)return;goalSelector.removeGoal(meleeAttack);goalSelector.removeGoal(arrowAttack);goalSelector.removeGoal(blastAttack);var held=getMainHandItem();goalSelector.addGoal(2,held.is(Items.BOW)?arrowAttack:held.getItem() instanceof CastingWandItem?blastAttack:meleeAttack);goalSelector.removeGoal(avoidPlayer);if(!tamed())goalSelector.addGoal(4,avoidPlayer);}
    @Override public void setItemSlot(EquipmentSlot slot,ItemStack stack){super.setItemSlot(slot,stack);if(!level().isClientSide&&slot==EquipmentSlot.MAINHAND)updateAINextTick=true;}
    @Override protected void populateDefaultEquipmentSlots(RandomSource rng,DifficultyInstance difficulty){switch(rng.nextInt(20)){case 0,12->{var wand=new ItemStack(R2Content.WAND.get());WandFocus.set(wand,new ItemStack(R5Content.PECH_FOCUS.get()));for(var aspect:List.of(Aspects.EARTH,Aspects.ENTROPY,Aspects.WATER))WandVis.add(wand,aspect,2+rng.nextInt(6));for(var aspect:List.of(Aspects.AIR,Aspects.FIRE,Aspects.ORDER))WandVis.add(wand,aspect,rng.nextInt(4));setItemSlot(EquipmentSlot.MAINHAND,wand);}case 1->setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.STONE_SWORD));case 3->setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.STONE_AXE));case 5->setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.IRON_SWORD));case 6->setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.IRON_AXE));case 7->setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.FISHING_ROD));case 8->setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.STONE_PICKAXE));case 9->setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.IRON_PICKAXE));case 2,4,10,11,13->setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.BOW));}}
    @Override public SpawnGroupData finalizeSpawn(ServerLevelAccessor level,DifficultyInstance difficulty,MobSpawnType reason,SpawnGroupData data){var result=super.finalizeSpawn(level,difficulty,reason,data);populateDefaultEquipmentSlots(random,difficulty);if(getMainHandItem().getItem() instanceof CastingWandItem){variant(1);setDropChance(EquipmentSlot.MAINHAND,.1f);}else if(!getMainHandItem().isEmpty()){if(getMainHandItem().is(Items.BOW))variant(2);populateDefaultEquipmentEnchantments(level,random,difficulty);}setCanPickUpLoot(random.nextFloat()<.75f*difficulty.getSpecialMultiplier());return result;}
    @Override public boolean removeWhenFarAway(double distance){int occupied=0;for(var stack:loot)if(!stack.isEmpty())++occupied;return occupied<5;}
    @Override public boolean requiresCustomPersistence(){return false;}
    @Override public void performRangedAttack(LivingEntity target,float strength){if(level().isClientSide)return;if(variant()==2){var lookup=registryAccess().lookupOrThrow(Registries.ENCHANTMENT);int power=EnchantmentHelper.getItemEnchantmentLevel(lookup.getOrThrow(Enchantments.POWER),getMainHandItem()),punch=EnchantmentHelper.getItemEnchantmentLevel(lookup.getOrThrow(Enchantments.PUNCH),getMainHandItem());var arrow=new PechArrow(level(),this,punch);double dx=target.getX()-getX(),dy=target.getY()+target.getEyeHeight()-1.1-arrow.getY(),dz=target.getZ()-getZ();float horizontal=Mth.sqrt((float)(dx*dx+dz*dz));arrow.shoot(dx,dy+horizontal*.2f,dz,1.6f,14-level().getDifficulty().getId()*4);arrow.setBaseDamage(strength*2f+random.nextGaussian()*.25+level().getDifficulty().getId()*.11f);if(power>0)arrow.setBaseDamage(arrow.getBaseDamage()+power*.5+.5);playSound(SoundEvents.ARROW_SHOOT,1,1/(random.nextFloat()*.4f+.8f));level().addFreshEntity(arrow);}else if(variant()==1){var blast=new PechBlast(level(),this,1,0,random.nextFloat()<.1f);double dx=target.getX()+target.getDeltaMovement().x-getX(),dy=target.getY()+target.getEyeHeight()-1.500000023841858-getY(),dz=target.getZ()+target.getDeltaMovement().z-getZ();float horizontal=Mth.sqrt((float)(dx*dx+dz*dz));blast.shoot(dx,dy+horizontal*.1f,dz,1.5f,4);playSound(R2Sounds.ICE.get(),.4f,1+random.nextFloat()*.1f);level().addFreshEntity(blast);}swing(InteractionHand.MAIN_HAND);}
    public void becomeAngryAt(LivingEntity attacker){angryAt=attacker;if(anger()<=0){level().broadcastEntityEvent(this,(byte)19);playSound(R2Sounds.PECH_CHARGE.get(),.4f,getVoicePitch());}setTarget(attacker);anger(400+random.nextInt(400));tamed(false);}
    @Override public boolean hurt(DamageSource source,float damage){if(isInvulnerableTo(source))return false;if(!level().isClientSide&&source.getEntity() instanceof Player player){for(var ally:level().getEntitiesOfClass(Pech.class,getBoundingBox().inflate(32,16,32)))if(ally!=this)ally.becomeAngryAt(player);becomeAngryAt(player);}return super.hurt(source,damage);}
    @Override public void tick(){if(mumble>0)mumble*=.75f;if(anger()>0)anger(anger()-1);if(!level().isClientSide&&anger()>0&&(angryAt==null||getTarget()==null)){if(angryAt==null)angryAt=level().getNearestPlayer(this,16);setTarget(angryAt);if(angryAt!=null){if(chargecount>0)--chargecount;if(chargecount==0){chargecount=100;playSound(R2Sounds.PECH_CHARGE.get(),.4f,getVoicePitch());}level().broadcastEntityEvent(this,(byte)17);}}if(level().isClientSide&&random.nextInt(15)==0&&anger()>0)emote(ParticleTypes.ANGRY_VILLAGER,1);if(level().isClientSide&&random.nextInt(25)==0&&tamed())emote(ParticleTypes.HAPPY_VILLAGER,1);super.tick();}
    @Override protected void customServerAiStep(){if(updateAINextTick){updateAINextTick=false;setCombatTask();}super.customServerAiStep();if(tickCount%40==0)heal(1);}
    @Override public void handleEntityEvent(byte event){if(event==16)mumble=(float)Math.PI;else if(event==17)mumble=(float)Math.PI*2;else if(event==18)emote(ParticleTypes.HAPPY_VILLAGER,5);else if(event==19){emote(ParticleTypes.ANGRY_VILLAGER,5);mumble=(float)Math.PI*2;}else super.handleEntityEvent(event);}
    private void emote(net.minecraft.core.particles.ParticleOptions particle,int count){for(int i=0;i<count;i++){double dx=random.nextGaussian()*.02,dy=random.nextGaussian()*.02,dz=random.nextGaussian()*.02;level().addParticle(particle,getX()+random.nextFloat()*getBbWidth()*2-getBbWidth(),getY()+.5+random.nextFloat()*getBbHeight(),getZ()+random.nextFloat()*getBbWidth()*2-getBbWidth(),dx,dy,dz);}}
    @Override public void playAmbientSound(){if(!level().isClientSide){if(random.nextInt(3)==0&&!level().getEntitiesOfClass(Pech.class,getBoundingBox().inflate(4,2,4),e->e!=this).isEmpty()){level().broadcastEntityEvent(this,(byte)17);playSound(R2Sounds.PECH_TRADE.get(),getSoundVolume(),getVoicePitch());return;}level().broadcastEntityEvent(this,(byte)16);}super.playAmbientSound();}
    @Override protected SoundEvent getAmbientSound(){return R2Sounds.PECH_IDLE.get();}@Override protected SoundEvent getHurtSound(DamageSource source){return R2Sounds.PECH_HIT.get();}@Override protected SoundEvent getDeathSound(){return R2Sounds.PECH_DEATH.get();}@Override protected float getSoundVolume(){return .4f;}@Override public int getAmbientSoundInterval(){return 120;}
    private static int explicitValue(ItemStack stack){if(stack.getItem() instanceof ManaBeanItem)return 1;if(stack.is(Items.GOLD_INGOT)||stack.is(Items.GOLDEN_APPLE)||stack.is(Items.ENCHANTED_GOLDEN_APPLE))return 2;if(stack.is(Items.ENDER_PEARL))return 3;if(stack.is(Items.DIAMOND))return 4;if(stack.is(Items.EMERALD))return 5;return 0;}
    public int value(ItemStack stack){if(stack.isEmpty())return 0;int explicit=explicitValue(stack);if(explicit!=0)return explicit;if(level() instanceof ServerLevel server)return Math.min(32,thaumcraft.data.ThaumcraftData.aspects(server.getServer(),stack).getOrDefault("lucrum",0));var data=thaumcraft.network.ClientKnowledge.aspects();var id=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).toString();return Math.min(32,thaumcraft.data.StackAspectRules.aspects(stack,data.objects().getOrDefault(id,Map.of()),data.modifiers()).getOrDefault("lucrum",0));}
    public boolean valued(ItemStack stack){return value(stack)>0;}
    public boolean canPickup(ItemStack stack){if(stack.isEmpty())return false;if(!tamed()&&explicitValue(stack)>0)return true;for(var held:loot)if(held.isEmpty()||ItemStack.isSameItemSameComponents(held,stack)&&stack.getCount()+held.getCount()<=held.getMaxStackSize())return true;return false;}
    public ItemStack pickup(ItemStack stack){if(stack.isEmpty())return stack;if(!tamed()&&valued(stack)){if(random.nextInt(10)<value(stack)){tamed(true);level().broadcastEntityEvent(this,(byte)18);}stack.shrink(1);return stack.isEmpty()?ItemStack.EMPTY:stack;}for(int i=0;i<loot.size();i++){var held=loot.get(i);if(!held.isEmpty()&&held.getCount()<held.getMaxStackSize()&&ItemStack.isSameItemSameComponents(held,stack)){int count=Math.min(stack.getCount(),held.getMaxStackSize()-held.getCount());held.grow(count);stack.shrink(count);if(stack.isEmpty())return ItemStack.EMPTY;}}for(int i=0;i<loot.size();i++)if(loot.get(i).isEmpty()){loot.set(i,stack.copy());return ItemStack.EMPTY;}return stack;}
    @Override protected InteractionResult mobInteract(Player player,InteractionHand hand){if(player.isShiftKeyDown()||player.getItemInHand(hand).is(Items.NAME_TAG))return InteractionResult.PASS;if(tamed()){if(player instanceof ServerPlayer server)server.openMenu(new SimpleMenuProvider((id,inventory,p)->new thaumcraft.menu.PechMenu(id,inventory,this),getName()),buffer->buffer.writeVarInt(getId()));return InteractionResult.sidedSuccess(level().isClientSide);}return super.mobInteract(player,hand);}
    @Override protected void dropCustomDeathLoot(ServerLevel level,DamageSource source,boolean recentlyHit){for(var stack:loot)if(!stack.isEmpty()&&level.random.nextFloat()<.88f)spawnAtLocation(stack.copy(),1.5f);int looting=source.getEntity() instanceof LivingEntity killer?EnchantmentHelper.getEnchantmentLevel(registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.LOOTING),killer):0;for(int i=0;i<1+looting;i++)if(random.nextBoolean())spawnAtLocation(ManaBeanItem.of(Aspects.PRIMALS.get(random.nextInt(6))),1.5f);if(level.random.nextInt(10)<1+looting)spawnAtLocation(new ItemStack(R5Content.LOOT_BAGS.get(0).get()),1.5f);if(recentlyHit&&random.nextFloat()<.025f+looting*.01f)spawnAtLocation(new ItemStack(R3Equipment.KNOWLEDGE_FRAGMENT.get()),1.5f);super.dropCustomDeathLoot(level,source,recentlyHit);}
    @Override public void addAdditionalSaveData(CompoundTag tag){super.addAdditionalSaveData(tag);tag.putByte("PechType",(byte)variant());tag.putShort("Anger",(short)anger());tag.putBoolean("Tamed",tamed());var list=new ListTag();for(var stack:loot)list.add(stack.saveOptional(registryAccess()));tag.put("Loot",list);}
    @Override public void readAdditionalSaveData(CompoundTag tag){super.readAdditionalSaveData(tag);if(tag.contains("PechType"))variant(tag.getByte("PechType"));anger(tag.getShort("Anger"));tamed(tag.getBoolean("Tamed"));var list=tag.getList("Loot",10);for(int i=0;i<9;i++)loot.set(i,ItemStack.parseOptional(registryAccess(),list.getCompound(i)));updateAINextTick=true;}
    private final class Pickup extends Goal {
        private ItemEntity target;private int count,penalty;
        Pickup(){setFlags(EnumSet.of(Flag.MOVE,Flag.LOOK));}
        public boolean canUse(){if(tickCount%5>0||--count>0)return false;double range=Double.MAX_VALUE;for(var entity:level().getEntitiesOfClass(ItemEntity.class,getBoundingBox().inflate(16))){double distance=entity.distanceToSqr(Pech.this);if(entity.getPersistentData().getBoolean("PechDrop")||!canPickup(entity.getItem())||distance>=range||distance>256)continue;range=distance;target=entity;}return target!=null;}
        public boolean canContinueToUse(){return target!=null&&target.isAlive()&&!getNavigation().isDone()&&target.distanceToSqr(Pech.this)<256;}
        public void start(){getNavigation().moveTo(getNavigation().createPath(target,0),getAttributeValue(Attributes.MOVEMENT_SPEED)*1.5);count=0;}public void stop(){target=null;}
        public void tick(){if(target==null)return;getLookControl().setLookAt(target,30,30);if(getSensing().hasLineOfSight(target)&&--count<=0){count=penalty+4+random.nextInt(4);getNavigation().moveTo(target,getAttributeValue(Attributes.MOVEMENT_SPEED)*1.5);var path=getNavigation().getPath();var end=path==null?null:path.getEndNode();penalty=end!=null&&target.distanceToSqr(end.x,end.y,end.z)<1?0:penalty+10;}if(distanceToSqr(target.getX(),target.getBoundingBox().minY,target.getZ())<=1.5){count=0;int before=target.getItem().getCount();var remainder=pickup(target.getItem());if(remainder.isEmpty())target.discard();else target.setItem(remainder);if(remainder.isEmpty()||remainder.getCount()!=before)target.playSound(SoundEvents.ITEM_PICKUP,.2f,((level().random.nextFloat()-level().random.nextFloat())*.7f+1)*2);}}
    }
}
